-- Local synthetic, rollback-only. Run before and after the correction: the first photo assertion regresses AUD-05.
begin;
select no_plan();
insert into auth.users(id,aud,role,email,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select ('95000000-0000-4000-8000-00000000000'||n)::uuid,'authenticated','authenticated','aud05-'||n||'@example.invalid',now(),'{}','{}',now(),now() from generate_series(1,4)n;
update public.users set role='superadmin' where id='95000000-0000-4000-8000-000000000001';
update public.users u set legal_acceptance_version=p.version,legal_acceptance_digest=p.digest,legal_acceptance_accepted_at=now() from public.legal_policy p where p.id and p.published and u.id::text like '95000000%';
insert into public.communities(id,name,created_by,owner_id) values('95100000-0000-4000-8000-000000000001','AUD05 synthetic','95000000-0000-4000-8000-000000000002','95000000-0000-4000-8000-000000000002');
insert into public.community_members(community_id,user_id) values('95100000-0000-4000-8000-000000000001','95000000-0000-4000-8000-000000000003'),('95100000-0000-4000-8000-000000000001','95000000-0000-4000-8000-000000000002');
create temp table fixture(name text primary key,id uuid default gen_random_uuid());
grant select on fixture to authenticated;
insert into fixture(name) select unnest(array['photo','text','poll','workout','achievement','permanent','active','ended','cancelled','support','failure','author','owner','unauthorized']);
insert into public.statuses(id,community_id,author_id,type,photo_path) select id,'95100000-0000-4000-8000-000000000001','95000000-0000-4000-8000-000000000003','photo','statusPhotos/95100000-0000-4000-8000-000000000001/'||id||'.webp' from fixture where name not in ('text','poll','workout','achievement');
insert into public.statuses(id,community_id,author_id,type,text) select id,'95100000-0000-4000-8000-000000000001','95000000-0000-4000-8000-000000000003','text','AUD05' from fixture where name='text';
insert into public.statuses(id,community_id,author_id,type,poll_question,poll_options) select id,'95100000-0000-4000-8000-000000000001','95000000-0000-4000-8000-000000000003','poll','AUD05?','[{"id":"a","label":"A"},{"id":"b","label":"B"}]' from fixture where name='poll';
insert into public.statuses(id,community_id,author_id,type,workout_title,workout_date,workout_location) select id,'95100000-0000-4000-8000-000000000001','95000000-0000-4000-8000-000000000003','workout','AUD05',now()+interval '1 day','Local' from fixture where name='workout';
insert into public.statuses(id,community_id,author_id,type,achievement_day,achievement_text) select id,'95100000-0000-4000-8000-000000000001','95000000-0000-4000-8000-000000000003','achievement','2026-10-13','AUD05' from fixture where name='achievement';
update public.statuses set retention_mode='no_auto_expiration',expires_at=null where id=(select id from fixture where name='permanent');
insert into public.status_votes(status_id,user_id,option_id) select id,'95000000-0000-4000-8000-000000000003','a' from fixture where name='poll';
insert into public.status_participants(status_id,user_id) select id,'95000000-0000-4000-8000-000000000003' from fixture where name='workout';
create temp table comments_ids as select gen_random_uuid() root,gen_random_uuid() reply;
insert into public.post_comments(id,status_id,author_id,root_comment_id,body,client_request_id) select root,f.id,'95000000-0000-4000-8000-000000000003',root,'AUD05 root',gen_random_uuid() from comments_ids c,fixture f where f.name='photo';
insert into public.post_comments(id,status_id,author_id,parent_comment_id,root_comment_id,body,client_request_id) select reply,f.id,'95000000-0000-4000-8000-000000000002',root,root,'AUD05 reply',gen_random_uuid() from comments_ids c,fixture f where f.name='photo';
insert into public.comment_likes(comment_id,user_id) select root,'95000000-0000-4000-8000-000000000002' from comments_ids;
insert into public.status_economy_votes(status_id,user_id,author_id,value) select id,'95000000-0000-4000-8000-000000000002','95000000-0000-4000-8000-000000000003',1 from fixture where name='photo';
insert into public.support_requests(user_id,kind,message,status_id,content_snapshot) select '95000000-0000-4000-8000-000000000002','report','AUD05 retained support snapshot',id,'{"text":"AUD05 evidence"}' from fixture where name='support';
create temp table support_before as select * from public.support_requests where status_id=(select id from fixture where name='support');
insert into public.promotions(owner_id,request_id,target_type,target_id,community_id,package_id,cash_amount,duration_days,status,started_at,expires_at,cancelled_at)
select '95000000-0000-4000-8000-000000000003','aud05-'||name,'post',id,'95100000-0000-4000-8000-000000000001','post_boost_3d',25,3,case when name='cancelled' then 'cancelled' else 'active' end,now()-interval '2 days',case when name='ended' then now()-interval '1 second' else now()+interval '1 day' end,case when name='cancelled' then now() end from fixture where name in ('active','ended','cancelled');
update public.statuses s set active_promotion_id=p.id,promoted=true,promoted_until=p.expires_at from public.promotions p where p.request_id like 'aud05-%' and p.target_id=s.id;
insert into public.economy_transactions(user_id,natural_key,asset,direction,amount,reason,reference_type,reference_id) select '95000000-0000-4000-8000-000000000003','aud05:'||id,'cash','debit',cash_amount,'promotion_purchase','promotion',id::text from public.promotions where request_id like 'aud05-%';
create temp table finance_before as select (select jsonb_agg(to_jsonb(t) order by id) from public.economy_transactions t) ledger,(select jsonb_agg(to_jsonb(t) order by user_id) from public.wallets t) wallets,(select jsonb_agg(to_jsonb(t) order by id) from public.cash_purchases t) purchases,(select jsonb_agg(to_jsonb(t)-'status'-'cancelled_at'-'cancelled_by'-'cancel_reason' order by id) from public.promotions t) promotions;
select set_config('request.jwt.claim.sub','95000000-0000-4000-8000-000000000001',true);
select public.queue_deletion('status',id) from fixture where name not in ('failure','author','owner','unauthorized');
create temp table results as select f.name,public.run_deletion_job(j.id) result from fixture f join public.deletion_jobs j on j.target_id=f.id;
select is((select result->>'complete' from results where name='photo'),'true','AUD05: photo deletion completes, not malformed array literal');
select is((select result->'photoPaths' from results where name='photo'),jsonb_build_array('statusPhotos/95100000-0000-4000-8000-000000000001/'||(select id from fixture where name='photo')||'.webp'),'photoPaths is a JSON array containing one literal path');
select is((select result->'photoPaths' from results where name='text'),'[]'::jsonb,'no photo means empty array');
select is((select count(*)::integer from public.statuses where id in(select id from fixture where name not in ('failure','author','owner','unauthorized'))),0,'all five post types and explicit permanent/support/promotion removals work');
select is((select count(*)::integer from public.storage_cleanup_tasks where source_id in(select id from fixture where name not in ('failure','author','owner','unauthorized'))),6,'AUD04 captures each deleted photo once, no non-photo task');
select is((select count(*)::integer from public.post_comments where status_id=(select id from fixture where name='photo')),0,'comments and replies cascade');
select is((select count(*)::integer from public.comment_likes where comment_id in(select root from comments_ids union select reply from comments_ids)),0,'comment votes cascade');
select is((select count(*)::integer from public.status_economy_votes where status_id=(select id from fixture where name='photo')),0,'post reactions cascade');
select is((select count(*)::integer from public.status_votes where status_id=(select id from fixture where name='poll')),0,'poll votes cascade');
select is((select count(*)::integer from public.status_participants where status_id=(select id from fixture where name='workout')),0,'workout participants cascade');
select is((select to_jsonb(s)-'status_id' from public.support_requests s where id=(select id from support_before)),(select to_jsonb(s)-'status_id' from support_before s),'support evidence retained exactly');
select ok((select status_id is null from public.support_requests where id=(select id from support_before)),'support target FK becomes NULL');
select is((select status from public.promotions where request_id='aud05-active'),'target_removed','existing manual moderation rule marks active promotion target removed');
select is((select status from public.promotions where request_id='aud05-cancelled'),'cancelled','cancelled promotion history unchanged');
select ok((select ledger is not distinct from (select jsonb_agg(to_jsonb(t) order by id) from public.economy_transactions t) and wallets is not distinct from (select jsonb_agg(to_jsonb(t) order by user_id) from public.wallets t) and purchases is not distinct from (select jsonb_agg(to_jsonb(t) order by id) from public.cash_purchases t) and promotions is not distinct from (select jsonb_agg(to_jsonb(t)-'status'-'cancelled_at'-'cancelled_by'-'cancel_reason' order by id) from public.promotions t) from finance_before),'ledger, purchases, balances and financial promotion values unchanged');
select ok(public.run_deletion_job((select j.id from public.deletion_jobs j join fixture f on f.id=j.target_id where f.name='photo'))->>'skipped'='true','repeated completed job is idempotent');
select public.queue_deletion('status',(select id from fixture where name='photo'));
select is((select count(*)::integer from public.deletion_jobs where target_id=(select id from fixture where name='photo')),1,'repeated request does not duplicate job');
select is((select count(*)::integer from public.storage_cleanup_tasks where source_id=(select id from fixture where name='photo')),1,'repeated request does not duplicate outbox task');
select ok(public.run_deletion_job(gen_random_uuid())->>'skipped'='true','missing job safely skips');
set local role authenticated;
select set_config('request.jwt.claim.sub','95000000-0000-4000-8000-000000000004',true);
select throws_ok($$select public.queue_deletion('status',(select id from fixture where name='unauthorized'))$$,'P0001','PERMISSION_DENIED','ordinary user cannot request administrative deletion');
with deleted as (delete from public.statuses where id=(select id from fixture where name='unauthorized') returning id) select is((select count(*)::integer from deleted),0,'RLS denies foreign deletion');
select set_config('request.jwt.claim.sub','95000000-0000-4000-8000-000000000003',true);
with deleted as (delete from public.statuses where id=(select id from fixture where name='author') returning id) select is((select count(*)::integer from deleted),1,'author direct deletion still works');
select set_config('request.jwt.claim.sub','95000000-0000-4000-8000-000000000002',true);
with deleted as (delete from public.statuses where id=(select id from fixture where name='owner') returning id) select is((select count(*)::integer from deleted),1,'community owner direct moderation works');
reset role;
select ok(not has_function_privilege('authenticated','public.run_deletion_job(uuid)','EXECUTE'),'worker execution restricted from authenticated');
select ok(not has_function_privilege('anon','public.run_deletion_job(uuid)','EXECUTE'),'worker execution restricted from anon');
select is((select proconfig::text from pg_proc where oid='public.run_deletion_job(uuid)'::regprocedure),'{"search_path=public, pg_temp"}','deployed search_path retained');
select set_config('request.jwt.claim.sub','95000000-0000-4000-8000-000000000001',true);
select public.queue_deletion('status',(select id from fixture where name='failure'));
create function pg_temp.fail_aud05() returns trigger language plpgsql as $$begin if old.id=(select id from pg_temp.fixture where name='failure') then raise exception 'AUD05_SYNTHETIC_FAILURE';end if;return old;end $$;
create trigger zz_aud05_failure after delete on public.statuses for each row execute function pg_temp.fail_aud05();
create temp table failed_result as select public.run_deletion_job(j.id) result from public.deletion_jobs j join fixture f on f.id=j.target_id where f.name='failure';
select ok((select result->>'error'='true' from failed_result),'DB trigger failure explicitly returned');
select is((select state from public.deletion_jobs where target_id=(select id from fixture where name='failure')),'pending','failed DB deletion remains pending for retry');
select ok(exists(select 1 from public.statuses where id=(select id from fixture where name='failure')),'failed DB deletion rolls back status');
select is((select count(*)::integer from public.storage_cleanup_tasks where source_id=(select id from fixture where name='failure')),0,'outbox capture rolled back with DB failure');
select matches((select last_error from public.deletion_jobs where target_id=(select id from fixture where name='failure')),'AUD05_SYNTHETIC_FAILURE','actual database error remains recorded');
drop trigger zz_aud05_failure on public.statuses;
select ok(public.run_deletion_job((select id from public.deletion_jobs where target_id=(select id from fixture where name='failure')))->>'complete'='true','retry after removing DB failure completes');
select * from finish();
rollback;
